scwin.gLdMktTp = js_market;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
}; // 세션의 시장구분

/**
 * @method
 * @name undo
 * @description undo 처리
 * @returns {void}
 * @hidden N
 */
scwin.undo = function() {
    dts_DocList.undoAll();
};

/**
 * @method
 * @name setMktCode
 * @description 세션ID의 시장정보를 셋팅한다.
 * @returns {void}
 * @hidden N
 */
scwin.setMktCode = function() {
    // 세션ID의 시장정보를 셋팅한다.

    if (scwin.gLdMktTp === "1") {
        // 유가
        rdo_MktTpCd.Format = "1^유가";
        rdo_MktTpCd.style.backgroundColor = "#d9e9fc";
        rdo_MktTpCd.Reset();
    } else if (scwin.gLdMktTp === "2") {
        // 코스닥
        // alert(rdo_MktTpCd.Format);
        rdo_MktTpCd.Format = "2^코스닥";
        rdo_MktTpCd.style.backgroundColor = "#d9e9fc";
        rdo_MktTpCd.Reset();
    } else if (scwin.gLdMktTp === "6") {
        // 코넥스
        // alert(rdo_MktTpCd.Format);
        rdo_MktTpCd.Format = "6^코넥스";
        rdo_MktTpCd.style.backgroundColor = "#d9e9fc";
        rdo_MktTpCd.Reset();
    } else {
        rdo_MktTpCd.Format = "9^전체,1^유가,2^코스닥,6^코넥스";
        rdo_MktTpCd.style.backgroundColor = "#d9e9fc";
        rdo_MktTpCd.Reset();
    }
    if (scwin.gLdMktTp === "3") {
        rdo_MktTpCd.setValue('9');
    } else {
        rdo_MktTpCd.setValue(scwin.gLdMktTp);
    }
    // alert(rdo_MktTpCd.ClassName);

    /*
    if (gLdMktTp == '1' || gLdMktTp=='2') {
    	rdo_MktTpCd.enable = false;
    } else{
    	rdo_MKT_ID.disabled = true;
    }
     */
};

